//! FancyMath tests.
//!
//! 1. Replays upstream's own self-test, FancyMath::runTests (cpp/core/fancymath.cpp), with its
//!    "T distribution tests" block extracted to fixtures/upstream-v1.16.5/unit/fancymath/.
//! 2. Bit-exactness against the real C++ (fixtures/upstream-v1.16.5/unit/oracle/fancymath.txt,
//!    generated by fancymath.cpp next to it from upstream's own object file): the
//!    DistributionTable search.cpp builds (StudentT with 3 degrees of freedom on [-50, 50]),
//!    every function on 65536 pseudo-random inputs, and fixed edge cases.
//!
//! Runs natively and on wasm32 (`just test-wasm`): the results depend on lgamma/exp/log/pow/expm1,
//! which on wasm come from port::math, not the platform libm.

#![allow(non_snake_case)]
#![allow(clippy::approx_constant, clippy::excessive_precision)] // upstream's literals, verbatim

