/// upstream: PI (fancymath.cpp) static — test-local copy (runTests uses it).
const PI: f64 = 3.1415926535897932384626433832795;

/// upstream: testApproxEq (fancymath.cpp) static — test-local copy.
fn test_approx_eq(x: f64, y: f64, tolerance: f64, msg_x: &str, msg_y: &str, file: &str, line: i32) {
  let max_diff: f64 = tolerance * cpp_max(x.abs(), cpp_max(y.abs(), 1.0));
  if (x - y).abs() <= max_diff {
    return;
  }
  Global::fatal_error(
    &(String::from("Failed approx equal: ")
      + msg_x
      + " "
      + msg_y
      + "\n"
      + "file: "
      + file
      + "\n"
      + "line: "
      + &Global::int_to_string(line)
      + "\n"
      + "Values: "
      + &strprintf!("%.17f", x)
      + " "
      + &strprintf!("%.17f", y)),
  );
}

/// upstream: APPROX_EQ (fancymath.cpp) — test-local copy.
macro_rules! APPROX_EQ {
  ($x:expr, $y:expr, $tolerance:expr) => {
    test_approx_eq(($x), ($y), ($tolerance), stringify!($x), stringify!($y), file!(), line!() as i32)
  };
}

use FancyMath as FM;

/// upstream: FancyMath::runTests (fancymath.cpp), replayed.
#[cfg_attr(not(target_arch = "wasm32"), test)]
#[cfg_attr(target_arch = "wasm32", wasm_bindgen_test::wasm_bindgen_test)]
